entries[177817] = { ["name"] = "Voodoo Powder", ["text"] = "Quest Item\nUnique\nUse: Use the power of Bwonsamdi's voodoo to save one of his followers from meeting him too early. Will not work if his follower has already perished." }
entries[177818] = { ["name"] = "Dark Mojo", ["text"] = "Quest Item\n\"This dark mojo animated the nearby undead of Nazmir towards the essence of Mueh'zala.\"" }
