entries[177835] = { ["name"] = "Louison's Gristle Cutter", ["text"] = "Quest Item\nUnique\nUse: Remove the head of a bloodtusk in Maldraxxus (4 Sec Cooldown)\n\"Well used, but still sharp.\"" }
