entries[177877] = { ["name"] = "Flask of Team Spirit", ["text"] = "Quest Item\nUse: Increase strength and confidence of allies splashed with this potion. (5 Sec Cooldown)\n\"Smells like team spirit.\"" }
entries[177878] = { ["name"] = "Animacone", ["text"] = "Quest Item\n\"The seed pulses gently with a dark, blue energy.\"" }
entries[177879] = { ["name"] = "Maldraxxi Bone Marrow", ["text"] = "Quest Item\nUnique (4)\n\"This bone marrow was mined from within Maldraxxus. Best not to think about it.\"" }
entries[177880] = { ["name"] = "Primordial Muck", ["text"] = "Quest Item\nUnique (20)\nUse: Tosses Primordial Muck to a nearby location." }
entries[177881] = { ["name"] = "Nadjia's Sinstone", ["text"] = "Quest Item\n\"The abhorrent actions of Viscountess Eak'le of Asquiron, premiere of the Order of Blades are described herein.\"" }
entries[177894] = { ["name"] = "Earthen Jar", ["text"] = "Quest Item\nUnique\nUse: Carefully gather the flame in the jar to transport it back to Bonesmith Heirmir. (3 Sec Cooldown)\n\"An earthenware jar, for storing and transporting hot coals.\"" }
entries[177895] = { ["name"] = "Warm Earthen Jar", ["text"] = "Quest Item\nUnique\n\"An earthenware jar, for storing and transporting hot coals. It is filled with lich fire and gives off an uncomfortable heat.\"" }
entries[177904] = { ["name"] = "Deathstone", ["text"] = "Quest Item\nUse: Travel to De Other Side.\n\"Looks something like a hearthstone, but with a touch more death.\"" }
entries[177905] = { ["name"] = "Deathstone", ["text"] = "Use: Leave the Other Side." }
entries[177946] = { ["name"] = "Desolate Leather Barding", ["text"] = "Use: Prevents the player from being dazed while mounted in the Shadowlands for 2 hrs.\n\nDuration is quadrupled for players trained in leatherworking.\nSell Price:" }
entries[177947] = { ["name"] = "Theotar's Lost Parasol", ["text"] = "Quest Item\nUnique" }
entries[177948] = { ["name"] = "Vulca's Lost Toolkit", ["text"] = "Quest Item\nUnique" }
entries[177949] = { ["name"] = "Tubbins's Lost Teapot", ["text"] = "Quest Item\nUnique" }
entries[177950] = { ["name"] = "Falk's Note", ["text"] = "Quest Item\nUnique\n\"Marked with splotches of blood, still wet to the touch.\"\n<Right Click to Read>" }
entries[177951] = { ["name"] = "Glimmerflies on Strings", ["text"] = "Binds when picked up\nToy\nUse: Summon a cluster of Glimmerflies to lift your spirit, granting you the ability to float over land and water. (5 Min Cooldown)\n\"Five of Bastion's finest glimmerflies tethered by strings of anima.\"\nSell Price:" }
entries[177953] = { ["name"] = "Untamed Spirit", ["text"] = "Queen's Conservatory\nQuest Item\nUse: Infuse a Wildseed of Regrowth with this spirit.\n\"This spirit contains the essence of an untamed being.\"\nSell Price:" }
entries[177954] = { ["name"] = "Condensed Anima Mote", ["text"] = "Quest Item\n\"A fraction of what the extractor was capable of producing, in better times.\"" }
entries[177955] = { ["name"] = "Spoiled Contaminant", ["text"] = "Binds when picked up\n\"The defeat of N'Zoth has rendered this specimen powerless.\"\nSell Price:" }
entries[177957] = { ["name"] = "Necessary Enhancers", ["text"] = "Binds when picked up\nUnique\n\"A special formula to improve one's combat abilities.\"\nSell Price:" }
entries[177958] = { ["name"] = "Duskwood Report", ["text"] = "Quest Item\nUnique\n\"The blood-soaked parchment lacks detail, but stresses the need for immediate reinforcements.\"" }
entries[177959] = { ["name"] = "Redridge Report", ["text"] = "Quest Item\nUnique\n\"Hastily written notes detailing a rise in the Scourge's presence.\"" }
entries[177960] = { ["name"] = "Elwynn Report", ["text"] = "Quest Item\nUnique\n\"A brief report on encounters against the Scourge.\"" }
entries[177961] = { ["name"] = "Plague Sample", ["text"] = "Binds when picked up\nUnique\n\"An unbroken vial of plague. It has markings on the vial that you cannot decipher.\"" }
entries[177962] = { ["name"] = "Enchant Chest - Eternal Stats", ["text"] = "Use: Permanently enchants a chest piece to increase primary stats by 80. Cannot be applied to items lower than level 10.\nSell Price:" }
entries[177963] = { ["name"] = "Purified Armor Fragments", ["text"] = "Quest Item\nUnique\n\"This black metal fragment shimmers with anima. There are parts of runes visible. It is no longer coated in green plague.\"" }
entries[177964] = { ["name"] = "Enchant Weapon - Force Multiplier", ["text"] = "+ 15 Corruption\nUse: Imbue an item with a malignant strain of N'Zoth's Corruption.\n\nDeadly Momentum\nYour critical hits have a chance to increase your Critical Strike by 9 for 30 sec, stacking up to 5 times.\nSell Price:" }
